  const dn = '\\mathbb{R} - \\{(2n + 1)\\tfrac{\\pi}{2}\\}', dm = '\\mathbb{R} - \\{n\\pi\\}', big = '(-\\infty, -1] \\cup [1, \\infty)';
  return table(['Function', 'Domain', 'Range', 'Smallest period'], [[D('\\sin x'), D('\\mathbb{R}'), D('[-1, 1]'), D('2\\pi')], [D('\\cos x'), D('\\mathbb{R}'), D('[-1, 1]'), D('2\\pi')], [D('\\tan x'), D(dn), D('\\mathbb{R}'), D('\\pi')], [D('\\cot x'), D(dm), D('\\mathbb{R}'), D('\\pi')], [D('\\sec x'), D(dn), D(big), D('2\\pi')], [D('\\operatorname{cosec} x'), D(dm), D(big), D('2\\pi')]], 'Table of domain, range and smallest positive period of the six trigonometric functions, with n an integer: sine and cosine are defined everywhere with range minus 1 to 1 and period 2 pi; tangent and secant exclude odd multiples of pi over 2; cotangent and cosecant exclude multiples of pi; tangent and cotangent take all real values with period pi; secant and cosecant have range outside the open interval from minus 1 to 1 and period 2 pi.', 'Here $n$ is any integer.');
