const pSin = plotF({ x: [-6.6, 6.6], y: [-1.6, 1.6], fns: [{ expr: 'sin(x)', label: '$y = \\sin x$' }], pts: [...[-2, -1, 0, 1, 2].map((k) => zero(k)), at(-3, 2, 1, '1'), at(-1, 2, -1, '-1'), at(1, 2, 1, '1'), at(3, 2, -1, '-1')] }, 'The graph of y equal to sine x from minus 6.6 to 6.6: a smooth wave between minus 1 and 1 that crosses the horizontal axis at minus 2 pi, minus pi, 0, pi and 2 pi, with peaks at minus 3 pi over 2 and pi over 2 and troughs at minus pi over 2 and 3 pi over 2.', r`$y = \sin x$: period $2\pi$, range $[-1, 1]$, zeros at $n\pi$.`);
const pCos = plotF({ x: [-6.6, 6.6], y: [-1.6, 1.6], fns: [{ expr: 'cos(x)', label: '$y = \\cos x$' }], pts: [...[-3, -1, 1, 3].map((k) => zero(k, 2)), [0, 1, '(0, 1)'], [PI, -1, '$(\\pi, -1)$'], [-PI, -1, '$(-\\pi, -1)$'], [2 * PI, 1, '$(2\\pi, 1)$'], [-2 * PI, 1, '$(-2\\pi, 1)$']] }, 'The graph of y equal to cosine x from minus 6.6 to 6.6: the sine wave shifted left by pi over 2, with peaks at minus 2 pi, 0 and 2 pi, troughs at minus pi and pi, and zeros at minus 3 pi over 2, minus pi over 2, pi over 2 and 3 pi over 2.', r`$y = \cos x$: period $2\pi$, range $[-1, 1]$, zeros at odd multiples of $\dfrac{\pi}{2}$.`);
const tanPieces = [[-4.55, -1.72], [-1.42, 1.42], [1.72, 4.55]];
const pTan = plotF({ x: [-5, 5], y: [-4, 4], fns: tanPieces.map((d, i) => ({ expr: 'tan(x)', domain: d, ...(i === 1 ? { label: '$y = \\tan x$' } : {}) })), pts: [zero(-1), zero(0), zero(1), at(1, 4, 1, '1'), at(-1, 4, -1, '-1')] }, 'The graph of y equal to tangent x as three separate branches, each rising from the bottom of the picture to the top, between the vertical dashed lines at minus 3 pi over 2, minus pi over 2, pi over 2 and 3 pi over 2. It crosses the horizontal axis at minus pi, 0 and pi and passes through pi over 4, 1 and minus pi over 4, minus 1.', r`$y = \tan x$: period $\pi$, all real values, asymptotes at odd multiples of $\dfrac{\pi}{2}$.`);
pTan.spec.vlines = vlinesAt([-3 * PI / 2, -PI / 2, PI / 2, 3 * PI / 2], 2, '$x = \\dfrac{\\pi}{2}$');
const pCosec = plotF({ x: [-6.5, 6.5], y: [-4, 4], fns: pieces(-2, 2).map(([a, b], i) => ({ expr: '1/sin(x)', domain: [a, b], ...(i === 2 ? { label: '$y = \\operatorname{cosec} x$' } : {}) })), pts: [at(1, 2, 1, '1'), at(-3, 2, 1, '1'), at(-1, 2, -1, '-1'), at(3, 2, -1, '-1')] }, 'The graph of y equal to cosecant x for x from minus 6.5 to 6.5 as four separate branches between the vertical dashed lines at minus 2 pi, minus pi, 0, pi and 2 pi. Branches above 1 lie over the intervals where sine is positive, with lowest points at minus 3 pi over 2 and pi over 2; branches below minus 1 lie where sine is negative, with highest points at minus pi over 2 and 3 pi over 2.', r`$y = \operatorname{cosec} x$: never between $-1$ and $1$; asymptotes at $n\pi$.`);
pCosec.spec.vlines = vlinesAt([-2 * PI, -PI, 0, PI, 2 * PI], 3, '$x = \\pi$');
const secBr = [[-6.5, -3 * PI / 2 - 0.18], [-3 * PI / 2 + 0.18, -PI / 2 - 0.18], [-PI / 2 + 0.18, PI / 2 - 0.18], [PI / 2 + 0.18, 3 * PI / 2 - 0.18], [3 * PI / 2 + 0.18, 6.5]];
const pSec = plotF({ x: [-6.5, 6.5], y: [-4, 4], fns: secBr.map(([a, b], i) => ({ expr: '1/cos(x)', domain: [a, b], ...(i === 2 ? { label: '$y = \\sec x$' } : {}) })), pts: [[0, 1, '(0, 1)'], [PI, -1, '$(\\pi, -1)$'], [-PI, -1, '$(-\\pi, -1)$'], [2 * PI, 1, '$(2\\pi, 1)$'], [-2 * PI, 1, '$(-2\\pi, 1)$']] }, 'The graph of y equal to secant x for x from minus 6.5 to 6.5 as five branches between vertical dashed lines at minus 3 pi over 2, minus pi over 2, pi over 2 and 3 pi over 2. Branches above 1 have lowest points at minus 2 pi, 0 and 2 pi; branches below minus 1 have highest points at minus pi and pi.', r`$y = \sec x$: never between $-1$ and $1$; asymptotes at odd multiples of $\dfrac{\pi}{2}$.`);
pSec.spec.vlines = vlinesAt([-3 * PI / 2, -PI / 2, PI / 2, 3 * PI / 2], 2, '$x = \\dfrac{\\pi}{2}$');
const pCot = plotF({ x: [-6.5, 6.5], y: [-4, 4], fns: pieces(-2, 2).map(([a, b], i) => ({ expr: 'cos(x)/sin(x)', domain: [a, b], ...(i === 2 ? { label: '$y = \\cot x$' } : {}) })), pts: [...[-3, -1, 1, 3].map((k) => zero(k, 2))] }, 'The graph of y equal to cotangent x for x from minus 6.5 to 6.5 as four branches, each falling from the top of the picture to the bottom between the vertical dashed lines at minus 2 pi, minus pi, 0, pi and 2 pi. It crosses the horizontal axis at minus 3 pi over 2, minus pi over 2, pi over 2 and 3 pi over 2.', r`$y = \cot x$: period $\pi$, all real values, zeros at odd multiples of $\dfrac{\pi}{2}$.`);
pCot.spec.vlines = vlinesAt([-2 * PI, -PI, 0, PI, 2 * PI], 3, '$x = \\pi$');
{
  must(G.every((x) => Math.abs(sin(x) - cos(x - PI / 2)) < 1e-12) && near(tan(PI / 4), 1) && near(tan(-PI / 4), -1) && near(csc(PI / 2), 1) && near(csc(-PI / 2), -1) && near(sec(0), 1) && near(sec(PI), -1) && near(cot(PI / 2), 0, 1e-12), 'graph points');
}
const pWe3 = plotF({ x: [-0.6, 6.9], y: [-0.5, 6], fns: [{ expr: '3 - 2cos(x)', label: '$y = 3 - 2\\cos x$' }], pts: [[0, 1, '(0, 1)'], [PI / 2, 3, '$\\left(\\dfrac{\\pi}{2}, 3\\right)$'], [PI, 5, '$(\\pi, 5)$'], [(3 * PI) / 2, 3, '$\\left(\\dfrac{3\\pi}{2}, 3\\right)$'], [2 * PI, 1, '$(2\\pi, 1)$']] }, 'The graph of y equal to 3 minus 2 cosine x for x from about minus 0.6 to 6.9: a wave between 1 and 5 with troughs of height 1 at 0 and 2 pi, a peak of height 5 at pi, and height 3 at pi over 2 and 3 pi over 2.', r`Least value $1$ at $x = 0$, greatest value $5$ at $x = \pi$; period $2\pi$.`);
