const summary2 = flow('LR', [['a', 'Reduce by whole turns'], ['b', 'Allied angle: even keeps, odd swaps'], ['c', 'Know domain, range, period'], ['d', 'Sketch the six graphs']], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Summary flow of Part 2: reduce angles by whole turns, apply the allied-angle rule where an even multiple keeps the function and an odd multiple swaps it, know the domain, range and period of each function, and sketch the six graphs.', 'Part 2 in one line.');
const tips2 = table(['Question type', 'How ISC marks are usually given'], [['Exact value of a large angle (2-3)', 'reduction 1, allied step 1, value 1'], ['Simplify an expression (3)', 'each allied result 1, final form 1'], ['Domain, range, period (2-3)', 'domain 1, range 1, period 1'], ['Sketch a graph (3)', 'shape 1, key points 1, asymptotes or intercepts 1']], 'Exam tips table for Part 2: exact values of large angles earn marks for the reduction, the allied step and the value; simplification earns a mark for each allied result and for the final form; domain, range and period earn a mark each; sketches earn marks for shape, key points and asymptotes or intercepts.', 'Show the reduction line, even when the value is obvious.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Angles and Trigonometric Functions - Part 1: Angles, radian measure and the unit circle',
  goals: ['Convert angles between degrees and radians', 'Find the arc length and the area of a sector', 'Define sine and cosine with the unit circle and use the basic identities', 'Find all six ratios from one ratio and the quadrant'],
  slides: [
    sl('title', 'Angles and Trigonometric Functions, Part 1', { b: 'From turning through an angle to the coordinates of a point on a circle.', v: titleCircle, n: 'Welcome to the chapter on angles and trigonometric functions. A turning door, a spinning wheel and a swinging pendulum all involve angles. In this part you will measure angles in degrees and in radians, find the length of an arc and the area of a sector, and then define sine and cosine as coordinates of a point on the unit circle.' }),
    sl('concept', 'What you will be able to do', { b: 'By the end of this part you can:', ul: ['Convert angles between degrees and radians', 'Find arc length and sector area', 'Define the functions from the unit circle', 'Find all six ratios from one ratio and the quadrant'], v: route1, n: 'Here is the plan. First we meet positive and negative angles and the two units for measuring them. Then we use radians to find arc lengths and sector areas. Finally we place a point on the unit circle, read off sine and cosine, and learn the identities and the signs in each quadrant.' }),
    sl('concept', 'Positive and negative angles', { b: 'An angle is made by turning an initial ray about its vertex. **Anticlockwise** turns give **positive** angles and **clockwise** turns give **negative** angles. Angles that end on the same ray are **coterminal**.', v: signed, n: 'An angle is formed by turning a ray about its end point. Turning anticlockwise gives a positive angle. Turning clockwise gives a negative angle. Here the same size of turn is shown both ways, plus fifty degrees and minus fifty degrees. Two angles that finish on the same ray are called coterminal, and they differ by whole turns.' }),
    sl('concept', 'Degrees and radians', { b: r`One full turn is $360^\circ$. A **radian** is the angle at the centre that cuts off an arc equal in length to the radius. In general $\theta = \dfrac{l}{r}$.`, v: twoRad, n: 'There are two common units. A degree is one three hundred and sixtieth of a full turn. A radian is defined by a circle itself: it is the angle at the centre that cuts off an arc as long as the radius. In the picture the arc is twice the radius, so the angle is two radians. In general the angle in radians is the arc divided by the radius.' }),
    sl('concept', 'Converting between the units', { b: r`A full turn is $2\pi$ radians, so $\pi$ radians $= 180^\circ$.`, v: convTbl, n: 'The circumference of a circle is two pi times the radius, so one full turn is two pi radians, and a half turn is pi radians, equal to one hundred and eighty degrees. To change degrees into radians multiply by pi over one hundred and eighty. To change radians into degrees multiply by one hundred and eighty over pi. The table lists the angles you will use most often.' }),
    sl('check', 'Quick check: radians to degrees', { b: 'Convert an angle given as a fraction of pi into degrees.', chk: 'fb1', n: 'Replace pi by one hundred and eighty degrees and simplify the fraction.' }),
    sl('example', 'Worked example 1: four conversions', { b: r`Convert $75^\circ$ and $-210^\circ$ to radians, and $\dfrac{13\pi}{18}$ rad and $2.5$ rad to degrees.`, ul: [r`$75^\circ = \dfrac{5\pi}{12}$ and $-210^\circ = -\dfrac{7\pi}{6}$`, r`$\dfrac{13\pi}{18}$ rad $= 130^\circ$`, r`$2.5$ rad $\approx 143.24^\circ$ (with $\pi = 3.14159$)`], v: we1Tbl, n: 'To go from degrees to radians multiply by pi over one hundred and eighty and cancel. Seventy five degrees becomes five pi over twelve. Minus two hundred and ten degrees becomes minus seven pi over six, keeping the sign. To go back, multiply by one hundred and eighty over pi. Thirteen pi over eighteen is one hundred and thirty degrees, and two and a half radians is about one hundred and forty three point two four degrees.' }),
    sl('check', 'Quick check: terminal sides', { b: 'Decide whether a positive and a negative angle end on the same ray.', chk: 'tf2', n: 'Add or subtract whole turns until both angles lie between zero and three hundred and sixty degrees.' }),
    sl('concept', 'Arc length', { b: r`In a circle of radius $r$, an arc that subtends the angle $\theta$ at the centre has length $l = r\theta$, **provided $\theta$ is in radians**.`, v: arcFig, n: 'Since the angle in radians is the arc divided by the radius, the arc length is the radius times the angle. This simple formula works only when the angle is in radians. If the angle is given in degrees, convert it first, or use pi times r times theta over one hundred and eighty.' }),
    sl('concept', 'Area of a sector', { b: r`A sector with radius $r$ and angle $\theta$ (radians) has area $A = \dfrac{1}{2}r^2\theta = \dfrac{1}{2}rl$.`, v: areaTbl, n: 'A sector is a fraction of the whole disc. The fraction is theta over two pi, so the area is theta over two pi times pi r squared, which simplifies to half r squared theta. Replacing r theta by the arc length gives the equally useful form, half times radius times arc. The table shows both units side by side.' }),
    sl('example', 'Worked example 2: the beam of a lamp', { b: r`A lamp in an imagined lighthouse lights a sector of sea of radius $21$ km through $80^\circ$. Find the length of the outer boundary and the area lit. Use $\pi = \dfrac{22}{7}$.`, ul: [r`$\theta = 80^\circ = \dfrac{4\pi}{9}$ rad`, r`$l = 21 \times \dfrac{4\pi}{9} = \dfrac{28\pi}{3} \approx 29.33$ km`, r`$A = \dfrac{1}{2} \times 441 \times \dfrac{4\pi}{9} = 98\pi = 308$ km$^2$`], v: we2Tbl, n: 'First change eighty degrees to radians: four pi over nine. The arc is twenty one times four pi over nine, which is twenty eight pi over three, about twenty nine point three three kilometres. The area is half times four hundred and forty one times four pi over nine, which is ninety eight pi. Using twenty two over seven for pi, that is three hundred and eight square kilometres.' }),
    sl('check', 'Quick check: an arc from a radian angle', { b: 'Find an arc length from a radius and an angle in radians.', chk: 'fb2', n: 'The angle is already in radians, so multiply it by the radius.' }),
    sl('example', 'Worked example 3: arc and area given', { b: r`A sector has an arc of length $12$ cm and an area of $36$ cm$^2$. Find the radius, the angle in radians and the angle in degrees.`, ul: [r`$A = \dfrac{1}{2}rl$ gives $36 = \dfrac{1}{2} \times r \times 12$, so $r = 6$ cm`, r`$\theta = \dfrac{l}{r} = \dfrac{12}{6} = 2$ rad`, r`$2$ rad $\approx 114.59^\circ$`], v: we3Tbl, n: 'When both the arc and the area are given, use the area formula with the arc first. Half times r times twelve equals thirty six, so r is six centimetres. Then the angle is the arc over the radius, twelve over six, which is two radians. In degrees that is about one hundred and fourteen point five nine degrees.' }),
    sl('concept', 'The unit circle definition', { b: r`Turn through $\theta$ from the point $(1, 0)$ on the circle $x^2 + y^2 = 1$ and reach $P$. Then $\cos\theta$ is the $x$-coordinate of $P$ and $\sin\theta$ is its $y$-coordinate.`, v: circle125, n: 'Now we define the functions for any angle. Take the circle of radius one about the origin. Start at the point one, zero and turn through the angle theta. The point you reach has two coordinates. The horizontal coordinate is cosine theta and the vertical coordinate is sine theta. Tangent is sine over cosine, and the other three are reciprocals.' }),
    sl('concept', 'Basic identities', { b: r`The point $(\cos\theta, \sin\theta)$ lies on $x^2 + y^2 = 1$, so $\sin^2\theta + \cos^2\theta = 1$ for **every** real $\theta$.`, v: idTbl, n: 'Because the point lies on the unit circle, its coordinates satisfy x squared plus y squared equals one. That gives the main identity: sine squared plus cosine squared equals one, true for every angle. Dividing by cosine squared or by sine squared gives the two companion identities, which hold only where the denominators are not zero. Tangent, cotangent, secant and cosecant are quotients or reciprocals.' }),
    sl('check', 'Quick check: an identity at a special angle', { b: 'Test the main identity where tangent is undefined.', chk: 'tf1', n: 'Does the main identity need any division? Compare with the companion identities.' }),
    sl('concept', 'Signs in the four quadrants', { b: 'The signs follow from the coordinates of $P$: cosine is the $x$-coordinate, sine is the $y$-coordinate. In quadrant I all six are positive; in II sine and cosecant; in III tangent and cotangent; in IV cosine and secant.', v: quadFig, n: 'The signs depend on where the point lies. In the first quadrant both coordinates are positive, so all six functions are positive. In the second quadrant only the vertical coordinate is positive, so sine and its reciprocal are positive. In the third quadrant both are negative, so their ratio, tangent, is positive. In the fourth quadrant only cosine and secant are positive.' }),
    sl('example', 'Worked example 4: all six from one', { b: r`If $\cos\theta = \dfrac{20}{29}$ and $\theta$ lies in the fourth quadrant, find the other five functions.`, ul: [r`$\sin^2\theta = 1 - \dfrac{400}{841} = \dfrac{441}{841}$, so $\sin\theta = -\dfrac{21}{29}$`, r`$\tan\theta = -\dfrac{21}{20}$`, r`$\operatorname{cosec}\theta = -\dfrac{29}{21}$, $\sec\theta = \dfrac{29}{20}$, $\cot\theta = -\dfrac{20}{21}$`], v: we4Tbl, n: 'Use the main identity to find the size of sine. Sine squared is one minus four hundred over eight hundred and forty one, which is four hundred and forty one over eight hundred and forty one, so sine has size twenty one over twenty nine. In the fourth quadrant sine is negative. The tangent follows by division, and the reciprocals by inverting.' }),
    sl('example', 'Worked example 5: proving an identity', { b: r`Prove that $\dfrac{\sin\theta}{1 + \cos\theta} + \dfrac{1 + \cos\theta}{\sin\theta} = 2\operatorname{cosec}\theta$.`, ul: ['Combine over a common denominator', r`Expand and use $\sin^2\theta + \cos^2\theta = 1$`, r`Cancel $1 + \cos\theta$`], v: we5Tbl, n: 'Work on the left side only. Put both fractions over the common denominator sine times one plus cosine. The numerator is sine squared plus the square of one plus cosine. Expanding and using the main identity turns it into two plus two cosine. Factor out two, cancel one plus cosine, and what remains is two over sine, which is two cosecant theta.' }),
    sl('summary', 'Summary', { ul: [r`$\pi$ rad $= 180^\circ$; $\theta = \dfrac{l}{r}$`, r`$l = r\theta$ and $A = \dfrac{1}{2}r^2\theta$ (radians)`, r`$P = (\cos\theta, \sin\theta)$ on the unit circle`, r`$\sin^2\theta + \cos^2\theta = 1$; signs by quadrant`], v: summary1, n: 'To sum up. A radian is arc divided by radius, and pi radians make one hundred and eighty degrees. With the angle in radians the arc is r theta and the sector area is half r squared theta. On the unit circle cosine and sine are the coordinates of the point. They satisfy the main identity, and their signs depend on the quadrant.' }),
    sl('exam-tips', 'Exam tips', { ul: [r`Convert to radians **before** using $l = r\theta$`, 'Name the quadrant before choosing a sign', 'In a proof, work on one side and state the identity used', r`Do not write $\sin^2\theta = \sin\theta^2$`], v: tips1, n: 'In the examination, change degrees to radians before using the arc formula. When finding a ratio from another, decide the quadrant first and then choose the sign. In a proof, start from one side only and name the identity you use at each step. And take care with notation: sine squared theta means the square of sine theta.' }),
  ],
});

